package dashboard.enterprise.agent.llm.validation;import dashboard.enterprise.agent.llm.model.LlmResponse;import java.util.Set;public final class StructuredOutputValidator{public void validate(LlmResponse response,Set<String> requiredFields){if(response==null||!response.successful())throw new IllegalArgumentException("Successful LLM response is required.");for(String field:requiredFields==null?Set.<String>of():requiredFields){if(!response.structuredOutput().containsKey(field))throw new IllegalArgumentException("Structured LLM output is missing field: "+field);}}}
